import React from 'react';
import './design.css';
import NavBar from ""

const DesignIdeas = () => {
  return (
    <div>
      {/* Banner at the top as an image */}
      <div className="banner">
        <img src="/Images/Designs/banner.png" alt="Design Ideas Banner" />
      </div>

      {/* Main content */}
      <div className="content">
        <h2>Design Ideas Content</h2>
        <p>This area can showcase various design ideas and layouts.</p>
      </div>
    </div>
  );
};

export default DesignIdeas;
